import apiClient from './client'

export interface AIConfigRead {
  id: number
  enabled: boolean
  provider: string
  model: string
  api_key?: string | null
  api_base?: string | null
  auto_execute: boolean
  snapshot_enabled: boolean
  snapshot_keep_count: number
  max_context_lines: number
  auto_analyze: boolean
  rate_mode: string
  fixed_rate: number
  max_rate: number
}

export interface AIConfigUpdate {
  enabled?: boolean
  provider?: string
  model?: string
  api_key?: string
  api_base?: string
  auto_execute?: boolean
  snapshot_enabled?: boolean
  snapshot_keep_count?: number
  max_context_lines?: number
  auto_analyze?: boolean
  rate_mode?: string
  fixed_rate?: number
  max_rate?: number
}

export interface AIAnalysisRead {
  id: number
  incident_id: number
  analysis?: string | null
  reasoning?: string | null
  suggested_action?: string | null
  action_params?: Record<string, unknown> | null
  confidence?: number | null
  executed: boolean
  execution_result?: string | null
  heal_task_id?: string | null
  created_at: string
}

export interface AnalysisJobRead {
  id: number
  incident_id: number
  status: 'pending' | 'running' | 'success' | 'failed' | 'skipped'
  reason?: string | null
  created_at: string
  started_at?: string | null
  finished_at?: string | null
}

export interface AnalysisJobStatus {
  job: AnalysisJobRead | null
  analysis: AIAnalysisRead | null
}

export interface AIRateStatus {
  mode: string
  effective_rate: number
  adaptive_rate: number
  max_rate: number
  fixed_rate: number
  starts_last_minute: number
  avg_duration_ms: number | null
  measurement_count: number
}

export interface ConfirmAnalysisRequest {
  execute: boolean
}

export interface ConfirmAnalysisResponse {
  analysis_id: number
  executed: boolean
  message: string
  task_id?: string | null
}

export async function getAIConfig(): Promise<AIConfigRead> {
  const response = await apiClient.get<AIConfigRead>('/v1/ai/config')
  return response.data
}

export async function updateAIConfig(data: AIConfigUpdate): Promise<AIConfigRead> {
  const response = await apiClient.put<AIConfigRead>('/v1/ai/config', data)
  return response.data
}

export async function analyzeIncident(incidentId: number): Promise<AIAnalysisRead> {
  // AI 根因分析需等待 LLM 响应，可能耗时数十秒，单独放宽到 120s（不影响全局 30s 默认）
  const response = await apiClient.post<AIAnalysisRead>(
    `/v1/ai/analyze/${incidentId}`,
    undefined,
    { timeout: 120000 }
  )
  return response.data
}

export async function getAnalysisJobStatus(incidentId: number): Promise<AnalysisJobStatus> {
  const response = await apiClient.get<AnalysisJobStatus>(`/v1/ai/jobs/${incidentId}`)
  return response.data
}

export async function getAIRateStatus(): Promise<AIRateStatus> {
  const response = await apiClient.get<AIRateStatus>('/v1/ai/rate-status')
  return response.data
}

export async function confirmAnalysis(
  analysisId: number,
  data: ConfirmAnalysisRequest
): Promise<ConfirmAnalysisResponse> {
  const response = await apiClient.post<ConfirmAnalysisResponse>(
    `/v1/ai/confirm/${analysisId}`,
    data
  )
  return response.data
}
